def reach(startmin,startmax):
    times={src:set()}
    pred={}
    evs=[e for e in events if e[2]>=startmin]
    for u,v,t in evs:
        for a,b in ((u,v),(v,u)):
            if a==src:
                if startmin<=t<=startmax:
                    if t not in times.setdefault(b,set()):
                        times[b].add(t); pred[(b,t)]=(a,None)
                continue
            if a not in times: continue
            ok=any(ta<=t<=ta+delta for ta in times[a])
            if ok:
                s=times.setdefault(b,set())
                if t not in s:
                    s.add(t); pred[(b,t)]=(a,min(ta for ta in times[a] if ta<=t<=ta+delta))
    return times,pred
